    ArtifactMetrics = apps.get_model("trovi", "ArtifactMetrics")
    ArtifactVersionMetrics = apps.get_model("trovi", "ArtifactVersionMetrics")

    days = settings.ARTIFACT_RECENT_METRICS_DAYS
    recent = Q(timestamp__gte=timezone.now() - timezone.timedelta(days=days))

    def count(event_type, distinct=False, q=Q()):
        q &= Q(event_type=event_type)
        if distinct:
            return Count("event_origin", distinct=True, filter=q)
        return Count("pk", filter=q)

    newest = (
        ArtifactEvent.objects.filter(
            event_type__in=["verify", "verify_failed"], artifact_version__isnull=False
        )
        .order_by()
        .values("artifact_version", "event_origin")
        .annotate(newest=Max("pk"))
        .values("newest")
    )
    shared = {
        "access_count": count("launch"),
        "unique_access_count": count("launch", distinct=True),
        "unique_cell_execution_count": count("cell_execution", distinct=True),
    }
    verifications = {
        "verified_count": count("verify", distinct=True),
        "verify_failed_count": count("verify_failed", distinct=True),
    }

    def per(key, aggregates):
        counts = defaultdict(dict)
        for events, group in (
            (ArtifactEvent.objects.all(), aggregates),
            (ArtifactEvent.objects.filter(pk__in=newest), verifications),
        ):
            for row in events.order_by().values(key).annotate(**group):
                counts[row.pop(key)].update(row)
        return counts

    artifacts = per(
        "artifact",
        {
            **shared,
            "recent_access_count": count("launch", q=recent),
            "recent_unique_access_count": count("launch", distinct=True, q=recent),
        },
    )
    rows = []
    for pk, counter in Artifact.objects.values_list("pk", "access_count"):
        launches = artifacts[pk].get("access_count", 0)
        rows.append(
            ArtifactMetrics(
                artifact_id=pk,
                **{**artifacts[pk], "access_count": max(counter, launches)},
                access_count_baseline=max(counter - launches, 0),
            )
        )
    ArtifactMetrics.objects.bulk_create(rows)

    versions = per("artifact_version", shared)
    ArtifactVersionMetrics.objects.bulk_create(
        ArtifactVersionMetrics(artifact_version_id=pk, **versions[pk])
        for pk in ArtifactVersion.objects.values_list("pk", flat=True)
    )


